using System;
using LittleLeo.Variables;
using UnityEngine;

namespace Astrea;

public class HighlightHandler : MonoBehaviour
{
	[Header("Highlight")]
	[SerializeField]
	protected SpriteRenderer highlightSpriteRenderer;

	[SerializeField]
	private FloatReference highlightDurationReference;

	[SerializeField]
	private AnimationCurveReference highlightCurveReference;

	protected MaterialPropertyBlock mpb;

	private float highlightDuration => highlightDurationReference.Value;

	private AnimationCurve highlightCurve => highlightCurveReference.Value;

	private void Awake()
	{
		mpb = new MaterialPropertyBlock();
	}

	protected void HighLightAnimation(string property, float finalValue, Action afterHighlightAction = null)
	{
		HighLightAnimation(property, finalValue, highlightDuration, afterHighlightAction);
	}

	protected void HighLightAnimation(string property, float finalValue, float highlightDurationCustom, Action afterHighlightAction = null)
	{
		float startingValue = mpb.GetFloat(property);
		StartCoroutine(CoroutineUtility.CurveRoutine(highlightDurationCustom, highlightCurve, delegate(float t, float v)
		{
			highlightSpriteRenderer.SetRendererFloat(mpb, property, Mathf.Lerp(startingValue, finalValue, v));
		}, afterHighlightAction));
	}
}
